        depth, opened = 0, False
        for k in range(n, min(len(lines), n + 800) + 1):
            ln = re.sub(r'"(\\.|[^"\\])*"|' + r"'(\\.|[^'\\])*'", '""', lines[k - 1])
            ln = ln.split('//', 1)[0]
            for c in ln:
                if c == '{':
                    depth, opened = depth + 1, True
                elif c == '}':
                    depth -= 1
            if opened and depth <= 0:
                return k
        return n
    indent = len(lines[n - 1]) - len(lines[n - 1].lstrip())
    end, k = n, n + 1
    while k <= len(lines):
        ln = lines[k - 1]
        if ln.strip():
            ind = len(ln) - len(ln.lstrip())
            if ind > indent:
                end = k
            else:
                if ind == indent and re.match(r'end\b', ln.strip()):
                    end = k
                break
        k += 1
    return end


def find_code(rec, spec):
    f = Found(spec)
    rest = spec[len('code:'):]
    path, _, anchors = rest.partition('#')
    frm, _, to = anchors.partition('..')
    path = os.path.join(rec.root, path.strip())
    if not os.path.isfile(path):
        f.bad, f.missing = True, 'no such file: ' + rec.rel(path)
        return f
    if not frm.strip():
        f.bad, f.missing = True, 'a code: key names the line its declaration starts at, after #'
        return f
    lines = read_lines(path)
    want = norm(frm)
    starts = [n for n, ln in enumerate(lines, 1) if want in norm(ln)]
    if not starts:
        f.bad, f.missing = True, 'no line of %s holds "%s"' % (rec.rel(path), frm.strip())
        return f
    f.bad = len(starts) > 1
    braces = path.endswith(BRACES)
    spans = []
    for a in starts:
        b = decl_end(lines, a, braces)
        if to.strip():
            want_to = norm(to)
            later = [n for n in range(a + 1, len(lines) + 1) if want_to in norm(lines[n - 1])]
            if not later:
                f.bad, f.missing = True, 'no line of %s after :%d holds "%s"' % (rec.rel(path), a, to.strip())
                return f
            b = max(b, decl_end(lines, later[0], braces))
        spans.append((a, b))
    for a, b in spans:
        width = len(str(b))
        f.blocks.append(('== %s:%d-%d' % (rec.rel(path), a, b),
                         '\n'.join('%*d  %s' % (width, n, lines[n - 1]) for n in range(a, b + 1))))
    f.where = ', '.join('%s:%d-%d' % (rec.rel(path), a, b) for a, b in spans) + ('' if len(spans) == 1 else '  (%d lines hold it, not one)' % len(spans))
    return f

                  selfType)
    case _ => signal(o, errorMsg("Self type is not inferred for ", o)); o
  }
}

/* Matches if block is an atomic block. */
case SBlock(SExprInfo(span,parenthesized,resultType),
            loc, true, withinDo, exprs) =>
  /* Strip the "atomic" to avoid infinite recursion;
   * then set it back again */
  NF.remakeAtomic(
  forAtomic(SBlock(SExprInfo(span,parenthesized,resultType),
                   loc, false, withinDo, exprs),
            "an 'atomic' do block").asInstanceOf[Block])

/* Matches if block is not an atomic block. */
case SBlock(SExprInfo(span,parenthesized,resultType),
            loc, false, withinDo, exprs) => {
  val newLoc = loc match {
    case Some(l) =>
      Some(checkExpr(l, Types.REGION, errorString("Location of the block")))
    case None => loc
  }
  exprs.reverse match {
    case Nil =>
      SBlock(SExprInfo(span,parenthesized,Some(Types.VOID)),
             newLoc, false, withinDo, exprs)
    case last::rest =>
      val allButLast = rest.map((e: Expr) => checkExpr(e, Types.VOID,
                                                       errorString("Non-last expression in a block")))
      val lastExpr = checkExpr(last, expected)
      val newExprs = (lastExpr::allButLast).reverse
      SBlock(SExprInfo(span,parenthesized,getType(lastExpr)),
             newLoc, false, withinDo, newExprs)
  }
}

